<script>
document.addEventListener('DOMContentLoaded',()=>{
  const dialog=document.getElementById('category-dialog'),form=document.getElementById('category-form'),name=document.getElementById('category-name'),description=document.getElementById('category-description');
  const slugPreview=document.getElementById('category-slug-preview');const updateSlug=()=>{const slug=(name.value||'').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'-').replace(/^-+|-+$/g,'');slugPreview.textContent=slug||'A name with letters or numbers is required'};name?.addEventListener('input',updateSlug);
  const open=(editing=false,data={})=>{document.getElementById('category-dialog-title').textContent=editing?'Edit category':'Create category';document.getElementById('category-method').value=editing?'PUT':'POST';document.getElementById('category-endpoint').value=editing?`/api/admin/categories/${data.id}`:'/api/admin/categories';form.action=editing?@json(route('admin.api-mutate')):@json(route('categories.store'));document.getElementById('category-save').textContent=editing?'Save changes':'Create category';name.value=data.name||'';description.value=data.description||'';document.getElementById('category-form-error').hidden=true;updateSlug();dialog.showModal();name.focus()};
  document.getElementById('new-category')?.addEventListener('click',()=>open());document.querySelectorAll('.edit-category').forEach(button=>button.addEventListener('click',()=>open(true,button.dataset)));document.getElementById('category-cancel')?.addEventListener('click',()=>dialog.close());
  form?.addEventListener('submit',async event=>{if(!name.value.trim()||!slugPreview.textContent||slugPreview.textContent.startsWith('A name with')){event.preventDefault();const error=document.getElementById('category-form-error');error.textContent='Enter a category name containing at least one letter or number.';error.hidden=false;return}if(document.getElementById('category-method').value!=='POST')return;event.preventDefault();if(!form.reportValidity())return;const button=document.getElementById('category-save'),error=document.getElementById('category-form-error');button.disabled=true;button.textContent='Creating…';error.hidden=true;try{const response=await fetch(form.action,{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':form.querySelector('input[name="_token"]').value},body:new FormData(form)});const result=await response.json();if(!response.ok)throw new Error(result.message||Object.values(result.errors||{}).flat().join(' ')||'ProductService could not create this category.');window.location.assign(`${@json(route('categories.index'))}?created=1`)}catch(exception){error.textContent=exception.message;error.hidden=false;button.disabled=false;button.textContent='Create category'}});
  document.querySelectorAll('[data-category-status-form]').forEach(form=>form.addEventListener('submit',event=>{const active=form.dataset.active==='true';if(!window.confirm(`${active?'Deactivate':'Activate'} this category? ${active?'Products will keep their category association.':'It will be available for active catalog use.'}`))event.preventDefault()}));
  document.querySelectorAll('[data-category-delete]').forEach(form=>form.addEventListener('submit',event=>{if(!window.confirm(`Delete “${form.dataset.name}”? ProductService rejects deletion while any product is assigned to this category.`))event.preventDefault()}));
  const loading=document.getElementById('catalog-loading');document.getElementById('category-filters')?.addEventListener('submit',()=>{if(loading)loading.hidden=false});document.querySelectorAll('[data-category-status-form],[data-category-delete]').forEach(form=>form.addEventListener('submit',()=>{if(form.reportValidity?.()!==false&&loading)loading.hidden=false}));
  const brandSearch=document.getElementById('brand-search'),brandRows=[...document.querySelectorAll('[data-brand-row]')],brandEmpty=document.getElementById('brand-empty');brandSearch?.addEventListener('input',()=>{let visible=0;const q=brandSearch.value.trim().toLowerCase();brandRows.forEach(row=>{row.hidden=!row.dataset.name.includes(q);if(!row.hidden)visible++});if(brandEmpty)brandEmpty.hidden=visible!==0});
});
</script>
</body></html>
